#include <cstddef>
#include <utility>
#include <vector>

std::vector<std::pair<std::size_t, std::size_t>> splitRanges(std::size_t total, std::size_t parts)
{
    std::vector<std::pair<std::size_t, std::size_t>> out;
    if (parts == 0) return out;
    const std::size_t base{ total / parts };
    const std::size_t extra{ total % parts };       // the first `extra` ranges get one more item
    std::size_t at{ 0 };
    for (std::size_t i{ 0 }; i < parts; ++i)
    {
        const std::size_t size{ base + (i < extra ? 1 : 0) };
        out.push_back({ at, at + size });
        at += size;
    }
    return out;
}

unitTests:
using R = std::vector<std::pair<std::size_t, std::size_t>>;
TEST("even split") { CHECK(splitRanges(12, 4) == R({ { 0, 3 }, { 3, 6 }, { 6, 9 }, { 9, 12 } })); }
TEST("larger ranges first") { CHECK(splitRanges(10, 3) == R({ { 0, 4 }, { 4, 7 }, { 7, 10 } })); }
TEST("more parts than items") { CHECK(splitRanges(2, 4) == R({ { 0, 1 }, { 1, 2 }, { 2, 2 }, { 2, 2 } })); }
TEST("one part") { CHECK(splitRanges(7, 1) == R({ { 0, 7 } })); }
TEST("nothing to do") { CHECK(splitRanges(0, 3) == R({ { 0, 0 }, { 0, 0 }, { 0, 0 } })); }
TEST("no parts") { CHECK(splitRanges(5, 0).empty()); }
TEST("large numbers cover everything")
{
    const R r{ splitRanges(10'000'003, 8) };
    CHECK_EQ(r.front().first, std::size_t{ 0 });
    CHECK_EQ(r.back().second, std::size_t{ 10'000'003 });
    bool contiguous{ true };
    for (std::size_t i{ 1 }; i < r.size(); ++i) contiguous = contiguous && r[i].first == r[i - 1].second;
    CHECK(contiguous);
}

